1	// SPDX-License-Identifier: Apache-2.0
2	// CacheEngineBuilder — Library-Wrapper (REV 7.6, 2026-05-13)
3	//
4	// Diese main.cpp ist ein duenner Wrapper um die
5	// comdare::builder::ExperimentDriver-Library. Die volle Pipeline-Logik
6	// (Phase 1-7) und alle Diagnose-Outputs leben in der Library.
7	//
8	// Architektur (User-Direktive 2026-05-13): Die cache-engine bestimmt WIE
9	// gemessen wird (Builder, Codegen, ModuleLoader, Mikrobenchmark-Suite,
10	// Workload-Generator-Library) — die Diplomarbeit bestimmt WAS gemessen
11	// wird (Compile-time-XML-Configs + 3-Messreihen-Loop in
12	// Diplomarbeit/Code/messung_driver/).
13	//
14	// Aufruf:
15	//   comdare-cache-engine-builder <config_dir> <output_dir> [options]
16	//
17	//   <config_dir>   Directory containing 4 XML configs:
18	//                    cache_engine_permutations.xml
19	//                    search_algorithm_permutations.xml
20	//                    allocator_permutations.xml
21	//                    test_data_sets.xml
22	//   <output_dir>   Directory for generated modules + measurement output
23	//
24	// Optionen:
25	//   -h, --help           Show usage text and exit (status 0)
26	//   --enumerate-only     Skip codegen + execution; print descriptors only
27	//   --comdare-root=DIR   Path to comdare-cache-engine repo root
28	//                        (default: current working directory)
29	//   --skip-build         Generate sources + aggregator, do not invoke cmake
30	//   --quiet              Disable per-phase diagnostic output
31	
