46	using MessreihenMode = comdare::builder::ExperimentDriverOptions::MessreihenMode;
47	
48	inline constexpr std::string_view mode_prefix        = "--mode=";
49	inline constexpr std::string_view sample_rate_prefix = "--sample-rate=";
50	inline constexpr std::string_view sample_seed_prefix = "--sample-seed=";
51	
52	[[nodiscard]] constexpr std::string_view messreihen_mode_name(MessreihenMode mode) noexcept {
53	    switch (mode) {
54	        case MessreihenMode::Defined: return "defined";
55	        case MessreihenMode::Full: return "full";
56	        case MessreihenMode::FullSampled: return "full-sampled";
57	    }
58	    return "unknown";
59	}
60	
61	void print_usage(std::ostream& os) {
62	    os << "Usage: comdare-cache-engine-builder <config_dir> <output_dir> [options]\n\n"
63	       << "  <config_dir>   Directory containing 4 XML configs:\n"
64	       << "                   cache_engine_permutations.xml\n"
65	       << "                   search_algorithm_permutations.xml\n"
66	       << "                   allocator_permutations.xml\n"
67	       << "                   test_data_sets.xml\n"
68	       << "  <output_dir>   Directory for generated modules + measurement output\n\n"
69	       << "Options:\n"
70	       << "  -h, --help           Show this usage text and exit (status 0)\n"
71	       << "  --enumerate-only     Skip codegen + execution; print descriptors only\n"
72	       << "  --comdare-root=DIR   Path to comdare-cache-engine repo root\n"
73	       << "                       (default: current working directory)\n"
74	       << "  --mode=<defined|full|full-sampled>\n"
75	       << "                       Messreihen mode (default: full)\n"
76	       << "  --sample-rate=<N>    FullSampled sampling rate (default: 1000)\n"
77	       << "  --sample-seed=<N>    FullSampled sampling seed (default: 0)\n"
78	       << "  --skip-build         Generate sources + aggregator, do not invoke cmake\n"
79	       << "  --quiet              Disable per-phase diagnostic output\n\n"
80	       << "Note: This Builder is the cache-engine-Demo-Driver. The real\n"
81	       << "      Experiment-Orchestrator (3 Messreihen A/B/C) lives in\n"
82	       << "      Diplomarbeit/Code/messung_driver/ (REV 7.6).\n";
83	}
84	
85	} // namespace
86	
87	int main(int argc, char* argv[]) {
88	    // #193-D — -h/--help: Usage nach stdout + Status 0 (User-Self-Test: Programm-Einstieg auffindbar).
89	    for (int i = 1; i < argc; ++i) {
90	        std::string_view a{argv[i]};
91	        if (a == "--help" || a == "-h") {
92	            print_usage(std::cout);
93	            return 0;
94	        }
95	    }
96	
97	    if (argc < 3) {
98	        print_usage(std::cerr);
99	        return 1;
100	    }
101	
102	    comdare::builder::ExperimentDriverOptions opts;
103	    opts.config_dir   = std::filesystem::path{argv[1]};
104	    opts.output_dir   = std::filesystem::path{argv[2]};
105	    opts.comdare_root = std::filesystem::current_path();
106	    opts.verbose      = true;
107	
108	    for (int i = 3; i < argc; ++i) {
109	        std::string_view a{argv[i]};
110	        if (a == "--enumerate-only")
111	            opts.enumerate_only = true;
112	        else if (a == "--skip-build")
113	            opts.skip_build = true;
114	        else if (a == "--quiet")
115	            opts.verbose = false;
116	        else if (a.rfind("--comdare-root=", 0) == 0) {
117	            opts.comdare_root = std::filesystem::path{std::string{a.substr(15)}};
118	        } else if (a.rfind(mode_prefix, 0) == 0) {
119	            std::string_view m = a.substr(mode_prefix.size());
120	            if (m == "defined")
121	                opts.messreihen_mode = MessreihenMode::Defined;
122	            else if (m == "full")
123	                opts.messreihen_mode = MessreihenMode::Full;
124	            else if (m == "full-sampled")
125	                opts.messreihen_mode = MessreihenMode::FullSampled;
126	            else {
127	                std::cerr << "Unknown --mode: " << m << " (defined|full|full-sampled)\n";
128	                return 1;
129	            }
130	        } else if (a.rfind(sample_rate_prefix, 0) == 0) {
131	            std::string_view v = a.substr(sample_rate_prefix.size());
132	            std::uint32_t    r{};
133	            auto const [p, ec] = std::from_chars(v.data(), v.data() + v.size(), r);
134	            if (ec != std::errc{} || p != v.data() + v.size()) {
135	                std::cerr << "Bad --sample-rate: " << v << "\n";
136	                return 1;
137	            }
138	            opts.sample_rate = r;
139	        } else if (a.rfind(sample_seed_prefix, 0) == 0) {
140	            std::string_view v = a.substr(sample_seed_prefix.size());
141	            std::uint64_t    s{};
142	            auto const [p, ec] = std::from_chars(v.data(), v.data() + v.size(), s);
143	            if (ec != std::errc{} || p != v.data() + v.size()) {
144	                std::cerr << "Bad --sample-seed: " << v << "\n";
145	                return 1;
146	            }
147	            opts.sample_seed = s;
148	        } else {
149	            std::cerr << "Unknown option: " << a << "\n";
150	            print_usage(std::cerr);
151	            return 1;
152	        }
153	    }
154	
155	    std::cout << "==== CacheEngineBuilder (REV 7.6 Library-Wrapper) ====\n";
156	    std::cout << "Config       : " << opts.config_dir.string() << "\n";
157	    std::cout << "Output       : " << opts.output_dir.string() << "\n";
158	    std::cout << "Comdare-Root : " << opts.comdare_root.string() << "\n";
159	    std::cout << "Pipeline     : "
160	              << (opts.enumerate_only ? "enumerate-only" : (opts.skip_build ? "generate-only" : "full pipeline"))
161	              << "\n";
162	    std::cout << "Messreihe    : " << messreihen_mode_name(opts.messreihen_mode);
163	    if (opts.messreihen_mode == MessreihenMode::FullSampled) {
164	        std::cout << " (sample-rate=" << opts.sample_rate << ", sample-seed=" << opts.sample_seed << ")";
165	    }
166	    std::cout << "\n";
167	    std::cout << "Verbose      : " << (opts.verbose ? "ON" : "OFF") << "\n";
168	
169	    // Demo-Workload (klein, YCSB-C). Echte Workloads pro Messreihe sind in
170	    // Diplomarbeit/Code/messung_driver/ (3 Messreihen A/B/C mit eigenen Configs).
171	    comdare::builder::WorkloadOptions wopts;
172	    wopts.config.num_keys       = 1000;
173	    wopts.config.num_operations = 500;
174	    wopts.config.random_seed    = 42;
175	    wopts.workload              = comdare::workload_generator::YcsbWorkload::C;
176	
177	    comdare::builder::ExperimentDriver driver{opts};
178	    int const                          rc = driver.run_pipeline_full(wopts);
179	    if (rc != comdare::builder::status_ok) {
180	        std::cerr << "\n[CacheEngineBuilder] Pipeline failed (status=" << rc << ")\n";
181	        return rc;
182	    }
183	
184	    std::cout << "\n==== CacheEngineBuilder OK ====\n";
185	    return 0;
186	}
