82	// ── Per-node Value (§2): Observer-Statistics + Mess-Auswertung der Ebene ──
83	struct NodeValue {
84	    std::uint64_t measured_setting_count = 0; // gemessene Experiment-Einstellungen unter diesem Knoten
85	    std::uint64_t sum_total_cycles       = 0;
86	    std::uint64_t sum_op_count           = 0;
87	    bool          has_result             = false;
88	    // BR-3: ECHTER Per-Achsen-Observer-Snapshot (kein 4-uint64-Stub mehr), via observe_all/tier_observe.
89	    NodeObserverSnapshot observer{};
90	    bool                 observer_real = false; // true = via realem observe_all einer Komposition gezogen
91	    // L-74b (Doc 27 §3): die 3 Build-Achsen (page_type/09b/12) sind Build-KONSTANTEN (kein Laufzeit-Observer) →
92	    // der Knoten trägt ihre reale, ABI-gezogene DEFINITION statt eines Pseudo-Observers. build_def_real=true wenn
93	    // via read_build_variant gesetzt (gemessener Knoten), sonst false (SPARSE-Kontrast wie observer_real).
94	    ::comdare::cache_engine::anatomy::BuildVariantDefinitionV1 build_def{};
95	    bool                                                       build_def_real = false;
96	};
