98	enum class NodeKind { Static, Dynamic };
99	
100	class INodeDescription {
101	public:
102	    virtual ~INodeDescription()                                                        = default;
103	    [[nodiscard]] virtual NodeKind    kind() const noexcept                            = 0;
104	    [[nodiscard]] virtual std::string axis() const                                     = 0;
105	    [[nodiscard]] virtual std::string value() const                                    = 0;
106	    [[nodiscard]] virtual std::string serialize() const                                = 0;
107	    [[nodiscard]] virtual bool        contributes_to_signature() const noexcept        = 0;
108	    [[nodiscard]] virtual bool        contributes_to_pinned_signature() const noexcept = 0;
109	    [[nodiscard]] virtual bool        is_runtime_loop() const noexcept                 = 0;
110	    /// RÜCK-Referenz (Bidirektionalität, User 2026-06-02): die ID des AxisBlock, dem dieser Knoten gehört.
111	    /// Macht statische UND dynamische Knoten auf dem GESAMTBAUM-Objekt block-filterbar + -zuordbar.
112	    [[nodiscard]] virtual std::string block_id() const = 0;
113	};
114	
115	/// StaticAxisNode — compile-time-Entscheidung → je Static-Pfad eine Tier-Binary.
116	class StaticAxisNode final : public INodeDescription {
117	public:
118	    StaticAxisNode(std::string axis, std::string value, bool pinned, std::string block_id = {})
119	        : axis_{std::move(axis)}, value_{std::move(value)}, pinned_{pinned}, block_id_{std::move(block_id)} {}
120	    NodeKind           kind() const noexcept override { return NodeKind::Static; }
121	    std::string        axis() const override { return axis_; }
122	    std::string        value() const override { return value_; }
123	    std::string        serialize() const override { return axis_ + "=" + value_; }
124	    bool               contributes_to_signature() const noexcept override { return true; }
125	    bool               contributes_to_pinned_signature() const noexcept override { return pinned_; }
126	    bool               is_runtime_loop() const noexcept override { return false; }
127	    std::string        block_id() const override { return block_id_; } // Rück-Referenz auf den compile-time AxisBlock
128	    [[nodiscard]] bool pinned() const noexcept { return pinned_; }
129	
130	private:
131	    std::string axis_, value_;
132	    bool        pinned_;
133	    std::string block_id_;
134	};
135	
136	/// DynamicVariableNode — Laufzeit-Variable → VIRTUELLE for-Schleife (nicht materialisiert). Wird je
137	/// Schleifen-Punkt von der Factory erzeugt und in die Experiment-Einstellung akkumuliert.
138	class DynamicVariableNode final : public INodeDescription {
139	public:
140	    DynamicVariableNode(std::string axis, std::string var, std::string value, std::string block_id = {})
141	        : axis_{std::move(axis)}, var_{std::move(var)}, value_{std::move(value)}, block_id_{std::move(block_id)} {}
142	    NodeKind    kind() const noexcept override { return NodeKind::Dynamic; }
143	    std::string axis() const override { return axis_; }
144	    std::string value() const override { return value_; }
145	    std::string serialize() const override { return axis_ + "." + var_ + "=" + value_; }
146	    bool        contributes_to_signature() const noexcept override { return false; }
147	    bool        contributes_to_pinned_signature() const noexcept override { return false; }
148	    bool        is_runtime_loop() const noexcept override { return true; }
149	    std::string block_id() const override { return block_id_; } // Rück-Referenz auf den compile-time AxisBlock
150	    [[nodiscard]] std::string variable() const { return var_; }
151	
152	private:
153	    std::string axis_, var_, value_;
154	    std::string block_id_;
155	};
