157	class AbstractNodeFactory {
158	public:
159	    virtual ~AbstractNodeFactory() = default;
160	    [[nodiscard]] virtual std::unique_ptr<INodeDescription>
161	    make_static(std::string axis, std::string value, bool pinned, std::string block_id = {}) const = 0;
162	    [[nodiscard]] virtual std::unique_ptr<INodeDescription>
163	    make_dynamic(std::string axis, std::string var, std::string value, std::string block_id = {}) const = 0;
164	};
165	
166	class ExperimentNodeFactory final : public AbstractNodeFactory {
167	public:
168	    std::unique_ptr<INodeDescription> make_static(std::string axis, std::string value, bool pinned,
169	                                                  std::string block_id = {}) const override {
170	        return std::make_unique<StaticAxisNode>(std::move(axis), std::move(value), pinned, std::move(block_id));
171	    }
172	    std::unique_ptr<INodeDescription> make_dynamic(std::string axis, std::string var, std::string value,
173	                                                   std::string block_id = {}) const override {
174	        return std::make_unique<DynamicVariableNode>(std::move(axis), std::move(var), std::move(value),
175	                                                     std::move(block_id));
176	    }
177	};
