197	/// Dynamische Dimension = eine virtuelle (nicht materialisierte) for-Schleife über einer Binary.
198	struct DynamicDim {
199	    std::string              axis;
200	    std::string              variable;
201	    std::vector<std::string> values;
202	    std::string              block_id; // Rück-Referenz auf den compile-time AxisBlock (Bidirektionalität)
203	};
