34	[[nodiscard]] inline std::string ceb_sanitize(std::string_view s) {
35	    std::string out;
36	    out.reserve(s.size());
37	    for (char c : s) out += (std::isalnum(static_cast<unsigned char>(c)) ? c : '_');
38	    return out;
39	}
40	[[nodiscard]] inline std::string ceb_upper(std::string_view s) {
41	    std::string out;
42	    out.reserve(s.size());
43	    for (char c : s) out += static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
44	    return out;
45	}
46	/// Zerlegt einen Binary-Pfad ("axis=value/axis.sub=value/…") in (achse, wert)-Paare.
47	[[nodiscard]] inline std::vector<std::pair<std::string, std::string>> ceb_parse_path(std::string_view path) {
48	    std::vector<std::pair<std::string, std::string>> out;
49	    std::size_t                                      i = 0;
50	    while (i < path.size()) {
51	        std::size_t      slash = path.find('/', i);
52	        std::string_view seg   = path.substr(i, (slash == std::string_view::npos ? path.size() : slash) - i);
53	        std::size_t      eq    = seg.find('=');
54	        if (eq != std::string_view::npos)
55	            out.emplace_back(std::string{seg.substr(0, eq)}, std::string{seg.substr(eq + 1)});
56	        if (slash == std::string_view::npos) break;
57	        i = slash + 1;
58	    }
59	    return out;
60	}
