21	/// Reflektiert eine mp_list von Wrapper-Typen → ihre Wert-Namen (W::name()). mp_identity vermeidet, die
22	/// Wrapper default-zu-konstruieren (nur der Typ wird benötigt).
23	template <class List>
24	[[nodiscard]] inline std::vector<std::string> reflect_names() {
25	    std::vector<std::string> out;
26	    mp::mp_for_each<mp::mp_transform<mp::mp_identity, List>>([&](auto id) {
27	        using W = typename decltype(id)::type;
28	        out.emplace_back(std::string{W::name()});
29	    });
30	    return out;
31	}
