2	// KF-7 (2026-06-02) — RuntimeVariableLoop: der dynamische Laufzeit-Durchlauf am Prüf-Dock.
3	//
4	// Doc 26 §2 (Ausführungssemantik): die DYNAMISCHEN Knoten sind eine FOR-SCHLEIFE auf EINER bereits geladenen
5	// Tier-Binary — sie probieren nacheinander die Test-Einstellungen über die Variablen-Schnittstelle
6	// (Algorithm_Resource_Control, KF-4) durch und erzeugen KEINE neue Binary. Dieser Treiber realisiert genau das:
7	// er durchläuft die virtuelle Kartesik der dynamischen Dimensionen (DynamicDim, KF-9) auf EINEM geladenen
8	// IResourceControllableTier, wendet je Kombination den geklammerten Resource-Control-POD an (AlgorithmResource-
9	// Control, KF-4) und ruft je Einstellung einen Mess-Callback — alles OHNE Neu-Laden/Neu-Bauen der Binary.
10	//
11	// Variablen→POD-Feld-Abbildung (KF-4 ComdareResourceControlV1): thread_count/prefetch_distance/pool_budget_bytes/
12	// batch_size/inline_threshold_bytes. ARCHITEKTONISCHE Laufzeit-Ausnahmen (z.B. hw_prefetcher via MSR 0x1A4) sind
13	// KEIN POD-Feld → werden im Label geführt, aber erst vom SLURM/MSR-Launcher angewandt (KF-12, Cluster-gated).
14	//
15	// Schicht-Trennung: dies ist Builder-Seite (das WIE des Messens); die Tier-Binary bleibt unverändert. C++23.
16	
17	#include "experiment_tree.hpp"
18	#include "../algorithm_resource_control.hpp"
19	
20	#include <charconv>
21	#include <cstdint>
22	#include <string>
23	#include <vector>
24	
25	namespace comdare::cache_engine::builder::experiment {
26	
27	/// Eine angewandte Laufzeit-Einstellung (= ein dynamisches Blatt auf der geladenen Binary).
28	struct RuntimeSetting {
29	    std::string                       setting_label; // akkumulierte dyn. Belegung "axis.var=value/…"
30	    anatomy::ComdareResourceControlV1 requested{};   // gewünschte Werte (vor Clamp)
31	    anatomy::ComdareResourceControlV1 applied{};     // effektiv angewandt (nach Clamp auf caps∩env)
32	    std::uint64_t                     applied_axis_count = 0;
33	};
34	
35	class RuntimeVariableLoop {
36	public:
37	    /// env_limits = System-Ressourcenlimits als Obergrenze (z.B. verfügbare Kerne; 0 = unbegrenzt).
38	    explicit RuntimeVariableLoop(anatomy::ComdareResourceControlV1 env_limits = {}) noexcept : env_{env_limits} {}
39	
40	    /// Durchläuft die virtuelle Kartesik der dynamischen Dimensionen auf der GELADENEN Binary `tier`
41	    /// (NICHT neu geladen). visitor(RuntimeSetting const&) je Einstellung. Liefert die Einstellungszahl.
42	    template <class Visitor>
43	    std::size_t run(anatomy::IResourceControllableTier& tier, std::vector<DynamicDim> const& dims,
44	                    Visitor&& visitor) const {
45	        std::vector<std::string> assign;
46	        std::size_t              count = 0;
47	        expand(tier, dims, 0, assign, visitor, count);
48	        return count;
49	    }
50	
51	    /// Bildet einen Variablennamen auf das zuständige Resource-Control-POD-Feld ab (0 = unbekannt/architektonisch).
52	    static void set_field(anatomy::ComdareResourceControlV1& pod, std::string const& var, std::uint64_t v) noexcept {
53	        if (var == "thread_count")
54	            pod.thread_count = v;
55	        else if (var == "prefetch_distance")
56	            pod.prefetch_distance = v;
57	        else if (var == "pool_budget_bytes")
58	            pod.pool_budget_bytes = v;
59	        else if (var == "batch_size")
60	            pod.batch_size = v;
61	        else if (var == "inline_threshold_bytes")
62	            pod.inline_threshold_bytes = v;
63	        // sonst: architektonische Laufzeit-Ausnahme (hw_prefetcher/MSR …) → kein POD-Feld (KF-12-Launcher).
64	    }
65	
66	private:
67	    [[nodiscard]] static std::uint64_t parse_u64(std::string const& s) noexcept {
68	        std::uint64_t v = 0;
69	        std::from_chars(s.data(), s.data() + s.size(), v); // nicht-numerisch (z.B. "off") → 0
70	        return v;
71	    }
72	
73	    template <class Visitor>
74	    void expand(anatomy::IResourceControllableTier& tier, std::vector<DynamicDim> const& dims, std::size_t dim,
75	                std::vector<std::string>& assign, Visitor& visitor, std::size_t& count) const {
76	        if (dim >= dims.size()) {
77	            anatomy::ComdareResourceControlV1 req{};
78	            for (auto const& seg : assign) {
79	                std::size_t const eq  = seg.find('=');
80	                std::size_t const dot = seg.find('.');
81	                if (eq == std::string::npos) continue;
82	                std::string const var =
83	                    (dot != std::string::npos && dot < eq) ? seg.substr(dot + 1, eq - dot - 1) : seg.substr(0, eq);
84	                set_field(req, var, parse_u64(seg.substr(eq + 1)));
85	            }
86	            anatomy::ComdareResourceControlV1 caps{};
87	            tier.tier_query_resource_caps(&caps);
88	            anatomy::ComdareResourceControlV1 applied = AlgorithmResourceControl::clamp(req, caps, env_);
89	            std::uint64_t const               nax     = tier.tier_apply_resource_control(&applied);
90	
91	            std::string label;
92	            for (auto const& seg : assign) {
93	                if (!label.empty()) label += "/";
94	                label += seg;
95	            }
96	            RuntimeSetting s{std::move(label), req, applied, nax};
97	            visitor(s);
98	            ++count;
99	            return;
100	        }
101	        DynamicDim const& d = dims[dim];
102	        for (auto const& val : d.values) {
103	            assign.push_back(d.axis + "." + d.variable + "=" + val); // = DynamicVariableNode::serialize
104	            expand(tier, dims, dim + 1, assign, visitor, count);
105	            assign.pop_back();
106	        }
107	    }
108	
109	    anatomy::ComdareResourceControlV1 env_;
110	};
