19	class AlgorithmResourceControl {
20	public:
21	    /// Gewünschte Werte (z.B. aus runtime_dynamic des Profils; 0 = Feld nicht setzen).
22	    anatomy::ComdareResourceControlV1 desired{};
23	    /// Zusätzliche System-Ressourcenlimits als Obergrenze (0 = unbegrenzt), z.B. verfügbare Kerne.
24	    anatomy::ComdareResourceControlV1 env_limits{};
25	
26	    /// Wendet `desired` auf das Tier an, geklammert auf min(tier-caps, env_limits). Liefert die Zahl der
27	    /// Achsen, die den Wert real angenommen haben. tier == nullptr → 0 (sauberes Degradieren).
28	    [[nodiscard]] std::uint64_t apply_to(anatomy::IResourceControllableTier* tier) const noexcept {
29	        if (tier == nullptr) return 0;
30	        anatomy::ComdareResourceControlV1 caps{};
31	        tier->tier_query_resource_caps(&caps);
32	        anatomy::ComdareResourceControlV1 eff = clamp(desired, caps, env_limits);
33	        return tier->tier_apply_resource_control(&eff);
34	    }
35	
36	    /// Klammert jedes Feld auf min(cap, env). Semantik: want==0 → 0 (nicht setzen); cap==0 → Achse nicht
37	    /// steuerbar → 0; env==0 → keine zusätzliche Env-Grenze.
38	    [[nodiscard]] static anatomy::ComdareResourceControlV1
39	    clamp(anatomy::ComdareResourceControlV1 const& want, anatomy::ComdareResourceControlV1 const& caps,
40	          anatomy::ComdareResourceControlV1 const& env) noexcept {
41	        auto cl = [](std::uint64_t w, std::uint64_t cap, std::uint64_t e) -> std::uint64_t {
42	            if (w == 0) return 0;                      // nicht setzen
43	            std::uint64_t hi = cap;                    // Tier-Cap
44	            if (e != 0 && (hi == 0 || e < hi)) hi = e; // Env-Grenze ggf. strenger
45	            if (hi == 0) return 0;                     // Achse nicht steuerbar
46	            return (w > hi) ? hi : w;                  // auf Obergrenze klammern
47	        };
48	        anatomy::ComdareResourceControlV1 out{};
49	        out.thread_count      = cl(want.thread_count, caps.thread_count, env.thread_count);
50	        out.prefetch_distance = cl(want.prefetch_distance, caps.prefetch_distance, env.prefetch_distance);
51	        out.pool_budget_bytes = cl(want.pool_budget_bytes, caps.pool_budget_bytes, env.pool_budget_bytes);
52	        out.batch_size        = cl(want.batch_size, caps.batch_size, env.batch_size);
53	        out.inline_threshold_bytes =
54	            cl(want.inline_threshold_bytes, caps.inline_threshold_bytes, env.inline_threshold_bytes);
55	        return out;
56	    }
57	};
