36	// #193-A — CWD-unabhaengige, libs/-korrekte Aufloesung des SOTA-Profil-Verzeichnisses
37	// (algorithm_profiles/sota). Der historische Inline-Fallback zeigte auf das Vor-libs/-Move-
38	// Layout comdare_root/"cache_engine"/... (V41.F.6 verschob es nach libs/cache_engine/...) und
39	// war zusaetzlich CWD-abhaengig. Diese Aufloesung ist gegen die comdare_root-Semantik
40	// (Repo-Root vs. libs/-Wurzel vs. config_dir) robust: sie probiert an jedem Anker mehrere
41	// Layout-Varianten und laeuft zur Not aufwaerts bis zur Repo-Wurzel. Rueckgabe leer => kein
42	// Auto-Pickup (Aufrufer ueberspringt den Profil-Schritt wie zuvor).
43	[[nodiscard]] std::filesystem::path resolve_sota_profiles_dir(std::filesystem::path const& config_dir,
44	                                                              std::filesystem::path const& comdare_root) {
45	    namespace fs = std::filesystem;
46	    std::error_code ec;
47	
48	    // Relative Layout-Varianten, die 'algorithm_profiles/sota' beherbergen koennen:
49	    // Repo-Root (libs/cache_engine/...), libs/-Wurzel (cache_engine/...), config_dir-Stil (direkt).
50	    std::array<fs::path, 3> const rel_variants{
51	        fs::path{"libs"} / "cache_engine" / "algorithm_profiles" / "sota",
52	        fs::path{"cache_engine"} / "algorithm_profiles" / "sota",
53	        fs::path{"algorithm_profiles"} / "sota",
54	    };
55	
56	    // 1) Direkt an den uebergebenen Ankern (haelt bestehende korrekte Aufrufe unveraendert).
57	    for (auto const& anchor : {config_dir, comdare_root}) {
58	        for (auto const& rel : rel_variants) {
59	            auto cand = anchor / rel;
60	            if (fs::is_directory(cand, ec)) return cand;
61	        }
62	    }
63	
64	    // 2) Aufwaerts-Repo-Root-Discovery (CWD-unabhaengig): von jedem Anker Richtung Wurzel laufen.
65	    for (auto const& start : {config_dir, comdare_root, fs::current_path(ec)}) {
66	        auto dir = fs::weakly_canonical(start, ec);
67	        if (ec) {
68	            dir = start;
69	            ec.clear();
70	        }
71	        for (; !dir.empty(); dir = dir.parent_path()) {
72	            for (auto const& rel : rel_variants) {
73	                auto cand = dir / rel;
74	                if (fs::is_directory(cand, ec)) return cand;
75	            }
76	            if (dir == dir.root_path()) break; // Wurzel erreicht -> Abbruch (kein Endlos-Loop)
77	        }
78	    }
79	    return {};
80	}
