140	// Phase 2: CODEGEN (Modul-Source-Generation + Aggregator-CMakeLists)
141	// ─────────────────────────────────────────────────────────────────────────────
142	int ExperimentDriver::phase2_generate(std::vector<loop::PermutationDescriptor> const& descriptors) {
143	    try {
144	        std::filesystem::create_directories(opts_.output_dir);
145	        codegen::CodegenOptions co;
146	        co.output_root  = opts_.output_dir / "generated";
147	        co.comdare_root = opts_.comdare_root;
148	        co.prt_art_root = opts_.prt_art_root; // V18.1: propagiere fuer Multi-Path-Template-Lookup
149	        codegen::CodegenEngine cg{co};
150	
151	        if (opts_.verbose) { std::cout << "\n[Phase 2] Generating " << descriptors.size() << " modules ...\n"; }
152	
153	        std::vector<std::uint64_t> fingerprints;
154	        fingerprints.reserve(descriptors.size());
155	        for (auto const& d : descriptors) {
156	            cg.generate_module(d.cache_engine_perm, d.search_algorithm_perm, d.allocator_perm, d.fingerprint);
157	            fingerprints.push_back(d.fingerprint);
158	            if (opts_.verbose) { std::cout << "  Generated: " << d.id << "\n"; }
159	        }
160	
161	        // REV 7.6 V10.5 — Auto-Pickup von algorithm_profiles/sota/*.profile.xml
162	        // #193-A: CWD-unabhaengige, libs/-korrekte Aufloesung (s. resolve_sota_profiles_dir).
163	        auto profiles_dir = resolve_sota_profiles_dir(opts_.config_dir, opts_.comdare_root);
164	        if (std::filesystem::is_directory(profiles_dir)) {
165	            xml::XmlConfigParser parser;
166	            auto                 profiles = parser.load_sota_profiles(profiles_dir);
167	
168	            // REV 7.6 V10.6 — Messreihen-Mode-Filter (Defined/Full)
169	            std::size_t filtered_out = 0;
170	            if (opts_.messreihen_mode == ExperimentDriverOptions::MessreihenMode::Defined &&
171	                !opts_.sota_profile_filter.empty()) {
172	                auto& filter = opts_.sota_profile_filter;
173	                profiles.erase(std::remove_if(profiles.begin(), profiles.end(),
174	                                              [&](xml::AlgorithmProfile const& p) {
175	                                                  bool keep =
176	                                                      std::find(filter.begin(), filter.end(), p.id) != filter.end();
177	                                                  if (!keep) ++filtered_out;
178	                                                  return !keep;
179	                                              }),
180	                               profiles.end());
181	            }
182	
183	            if (opts_.verbose) {
184	                std::cout << "  [V10.5/V10.6] Auto-Pickup: " << profiles.size() << " SOTA-Profile aus "
185	                          << profiles_dir.string() << " (mode=" << messreihen_mode_name(opts_.messreihen_mode);
186	                if (filtered_out > 0) std::cout << ", " << filtered_out << " gefiltert";
187	                std::cout << ")\n";
188	            }
189	            std::size_t const profile_population = profiles.size();
190	            std::size_t       generated_profiles = 0;
191	            for (auto const& prof : profiles) {
192	                if (opts_.messreihen_mode == ExperimentDriverOptions::MessreihenMode::FullSampled &&
193	                    !loop::sample_keep(prof.id, opts_.sample_rate, opts_.sample_seed)) {
194	                    continue; // AP-5: deterministisch verworfen; Modul-Identitaet prof_fp bleibt unangetastet.
195	                }
196	                // Deterministischer Fingerprint aus Profil-id
197	                std::uint64_t prof_fp = std::hash<std::string>{}(prof.id) ^ 0xC0FFEE02ull;
198	                cg.generate_module_from_profile(prof, prof_fp);
199	                fingerprints.push_back(prof_fp);
200	                ++generated_profiles;
201	                if (opts_.verbose) {
202	                    std::cout << "    Profile-Modul: " << prof.id << " (paper_ref=" << prof.paper_ref << ", fp=0x"
203	                              << std::hex << prof_fp << std::dec << ")\n";
204	                }
205	            }
206	            if (opts_.messreihen_mode == ExperimentDriverOptions::MessreihenMode::FullSampled &&
207	                opts_.sample_rate >= loop::sampling_min_filtered_rate && profile_population > 0 &&
208	                generated_profiles == 0) {
209	                std::cerr << "[Phase 2] WARN: FullSampled 1:" << opts_.sample_rate
210	                          << " ergab 0 SOTA-Profile (Population=" << profile_population
211	                          << "); kleinere --sample-rate waehlen.\n";
212	            }
213	        }
214	
215	        cg.generate_aggregate_cmake(fingerprints);
216	
217	        if (opts_.verbose) { std::cout << "  Aggregator: " << cg.aggregate_cmake_path().string() << "\n"; }
218	    } catch (std::exception const& e) {
219	        std::cerr << "[Phase 2] codegen error: " << e.what() << "\n";
220	        return status_codegen_failed;
221	    }
222	    return status_ok;
223	}
