225	// REV 7.6 V13.2 — Hot-Compile-Helper fuer enable_runtime_codegen
226	// Erkennt fehlende Permutations-Module und kompiliert sie via cmake-Aufruf
227	// auf der bereits generierten source library nach.
228	namespace {
229	[[nodiscard]] bool module_binary_exists(std::filesystem::path const& dir, std::uint64_t fingerprint) {
230	    auto check_one = [&](std::string const& ext) {
231	        std::ostringstream name;
232	        name << "comdare_perm_" << std::hex << fingerprint << ext;
233	        return std::filesystem::exists(dir / name.str());
234	    };
235	#if defined(_WIN32)
236	    return check_one(".dll") || check_one(".lib");
237	#elif defined(__APPLE__)
238	    return check_one(".dylib") || check_one(".so");
239	#else
240	    return check_one(".so");
241	#endif
242	}
