264	// Phase 3: COMPILE (cmake configure + cmake --build)
265	// ─────────────────────────────────────────────────────────────────────────────
266	int ExperimentDriver::phase3_compile() {
267	    auto const bdir = build_dir_for(opts_.output_dir);
268	    std::filesystem::create_directories(bdir);
269	
270	    auto const generated = opts_.output_dir / "generated";
271	
272	    if (opts_.verbose) { std::cout << "\n[Phase 3] Configuring cmake subbuild under " << bdir.string() << " ...\n"; }
273	
274	    auto run_cmd = [this](std::string const& cmd) -> int {
275	        if (opts_.verbose) { std::cout << "  $ " << cmd << "\n"; }
276	        return std::system(cmd.c_str());
277	    };
278	
279	    std::string configure_cmd = "cmake -S \"" + generated.string() + "\" -B \"" + bdir.string() + "\"";
280	    int         rc            = run_cmd(configure_cmd);
281	    if (rc != 0) {
282	        std::cerr << "[Phase 3] cmake configure failed with exit " << rc << "\n";
283	        return status_cmake_configure_failed;
284	    }
285	
286	    std::string build_cmd = "cmake --build \"" + bdir.string() + "\" --target comdare_all_permutations";
287	    rc                    = run_cmd(build_cmd);
288	    if (rc != 0) {
289	        std::cerr << "[Phase 3] cmake --build failed with exit " << rc << "\n";
290	        return status_cmake_build_failed;
291	    }
292	
293	    if (opts_.verbose) { std::cout << "[Phase 3] OK\n"; }
294	    return status_ok;
295	}
