3	//
4	// Brückt das geparste Profil (comdare::builder::xml::ThesisProfile, KF-1) an den Baum-Kern (experiment_tree.hpp):
5	//   • Paper/Tier-Dimension (oben): Fanout = base_tiers (jeder = ein gepinntes Paper-Tupel).
6	//   • freigegebene permute_axes (mode.active_axes) → STATISCHE Ebenen (→ Binaries); cacheline → statische
7	//     Sub-Ebenen (line_size/alignment/sw_hint, compile-time).
8	//   • runtime_dynamic (thread_count/hw_prefetcher) → DYNAMISCHE Ebenen (Laufzeit-for-Schleife, Algorithm_Resource_Control).
9	// Werte: explizit aus dem Profil; fehlen sie, expandiert die AxisRegistry (permutation_axes.xml) die volle Liste.
10	// Doc architecture/26. C++23, header-only.
11	
12	#include "experiment_tree.hpp"
