21	/// Achsen-Wertebereiche aus permutation_axes.xml (axis-ref → volle Werteliste).
22	using AxisRegistry = std::map<std::string, std::vector<std::string>>;
23	
24	/// Baut die geordneten AxisLevels eines Modus aus dem Thesis-Profil.
25	[[nodiscard]] inline std::vector<AxisLevel> build_axis_levels(comdare::builder::xml::ThesisProfile const& tp,
26	                                                              std::string const&                          mode_name,
27	                                                              AxisRegistry const&                         registry) {
28	    std::vector<AxisLevel> levels;
29	
30	    // 1. Paper/Tier-Dimension (oben).
31	    {
32	        AxisLevel tier;
33	        tier.axis      = "tier";
34	        tier.is_static = true;
35	        for (auto const& t : tp.base_tiers) tier.values.push_back(t.id);
36	        if (!tier.values.empty()) levels.push_back(std::move(tier));
37	    }
38	
39	    // Modus auflösen (active_axes = freigegebene Achsen).
40	    comdare::builder::xml::ThesisMode const* mode = nullptr;
41	    for (auto const& m : tp.modes)
42	        if (m.name == mode_name) mode = &m;
43	    auto is_active = [&](std::string const& ref) -> bool {
44	        if (mode == nullptr) return true; // kein Modus → alle frei
45	        for (auto const& a : mode->active_axes)
46	            if (a == ref) return true;
47	        return false;
48	    };
49	
50	    // 2. Freigegebene permute_axes → statische Ebenen.
51	    for (auto const& ax : tp.permute_axes) {
52	        if (!is_active(ax.ref)) continue;
53	        if (ax.ref == "cacheline") { // compile-time → statische Sub-Ebenen (Binary-Identität)
54	            if (!ax.line_sizes.empty()) levels.push_back(AxisLevel{"cacheline.line_size", ax.line_sizes, true, ""});
55	            if (!ax.alignments.empty()) levels.push_back(AxisLevel{"cacheline.alignment", ax.alignments, true, ""});
56	            if (!ax.sw_prefetch_hints.empty())
57	                levels.push_back(AxisLevel{"cacheline.sw_hint", ax.sw_prefetch_hints, true, ""});
58	            continue;
59	        }
60	        std::vector<std::string> vals = ax.values; // explizit?
61	        if (vals.empty()) {                        // sonst volle Liste aus dem Registry
62	            auto it = registry.find(ax.ref);
63	            if (it != registry.end()) vals = it->second;
64	        }
65	        if (!vals.empty()) levels.push_back(AxisLevel{ax.ref, std::move(vals), true, ""});
66	    }
67	
68	    // 3. runtime_dynamic → dynamische Ebenen (Laufzeit-for-Schleife). DIE EINZIGE Quelle dieser Dimensionen
69	    //    (Inc2 dyn-Dim-Konsolidierung, 2026-06-18): vorher hingen profile_runner::profile_dynamic_dims dieselben
70	    //    Dimensionen ein ZWEITES Mal an (Doppelquelle). Jetzt emittiert build_axis_levels sie selbst — vollstaendig
71	    //    + mit den Mess-Pfad-Konventionen (concurrency.thread_count / prefetch.hw_prefetcher + Wiederholungs-Achse
72	    //    repetition.repetition_index, KF-10). Die binary_id wird davon NICHT beruehrt (is_static=false → der Baum
73	    //    filtert sie via static_filter() raus; Round-Trip bewiesen). variable/block_id = ComdareResourceControlV1-
74	    //    Feldname bzw. architektonische Ausnahme (repetition_index ist KEIN POD-Feld → set_field ignoriert es).
75	    if (!tp.thread_counts.empty())
76	        levels.push_back(AxisLevel{"concurrency", tp.thread_counts, false, "thread_count", "concurrency"});
77	    if (!tp.hw_prefetcher.empty())
78	        levels.push_back(AxisLevel{"prefetch", tp.hw_prefetcher, false, "hw_prefetcher", "prefetch"});
79	    // Wiederholungs-Achse (D, KF-10): immer vorhanden (Default 3, separat, nie interpoliert). repetitions<=0 → 1.
80	    {
81	        int const                reps = (tp.repetitions <= 0) ? 1 : tp.repetitions;
82	        std::vector<std::string> rep_vals;
83	        rep_vals.reserve(static_cast<std::size_t>(reps));
84	        for (int r = 0; r < reps; ++r) rep_vals.push_back(std::to_string(r));
85	        levels.push_back(AxisLevel{"repetition", std::move(rep_vals), false, "repetition_index", "repetition"});
86	    }
87	
88	    return levels;
89	}
