20	/// strip_all_elaborated (2026-06-03, L-LAZY-E2E) — entfernt ALLE (auch INNEN-liegenden) MSVC-Elaborated-Type-
21	/// Keywords aus einem FQ-Typ-Namen. type_name<T>() schält nur den ÄUSSEREN "class "/"struct " (type_name.hpp);
22	/// MSVC rendert in __FUNCSIG__ aber AUCH jedes verschachtelte Template-Argument so, z.B.
23	/// `ObservableNodeType<class NS::Node4NodeType>`. Würde das innere `class ` in den emittierten C++-Quelltext
24	/// geschrieben, ist es ein Syntaxfehler (C2760 „class hier nicht erwartet", Befund 2026-06-03 bei den
25	/// Observable*<…>-Wrappern node/layout/serialization/telemetry). Da der Emitter den Namen als ECHTEN Quelltext
26	/// schreibt, ist hier (host-seitig, std::string) der richtige Ort, die Tokens überall zu entfernen.
27	/// SICHER: "class "/"struct "/"enum "/"union " (mit folgendem Trenner) sind in __FUNCSIG__ ausschließlich
28	/// Elaborated-Specifier — ein Identifier kann kein Leerzeichen enthalten → keine Falsch-Treffer.
29	[[nodiscard]] inline std::string strip_all_elaborated(std::string_view t) {
30	    static constexpr std::string_view kws[] = {"class ", "struct ", "enum ", "union "};
31	    std::string                       out;
32	    out.reserve(t.size());
33	    for (std::size_t i = 0; i < t.size();) {
34	        bool matched = false;
35	        for (std::string_view kw : kws)
36	            if (i + kw.size() <= t.size() && t.substr(i, kw.size()) == kw) {
37	                i += kw.size();
38	                matched = true;
39	                break;
40	            }
41	        if (!matched) out += t[i++];
42	    }
43	    return out;
44	}
45	
46	/// adhoc_macro_args<C>() — die 19 FQ-Achsen-Typ-Namen einer Composition C als Komma-getrennter Block
47	/// (Argument für COMDARE_DEFINE_ANATOMY_MODULE_ADHOC). Reihenfolge = AdHocComposition<T0..T18>
48	/// (17 Such-Achsen + queuing q1/q2, Doc 30 §8.0). Jeder Name wird via strip_all_elaborated von INNEN-liegenden
49	/// "class "/"struct "-Keywords befreit (sonst Syntaxfehler bei Wrapper<class Inner>-Slots).
50	template <class C>
51	[[nodiscard]] std::string adhoc_macro_args() {
52	    std::string s;
53	    auto        add = [&](std::string_view t) {
54	        if (!s.empty()) s += ",\n    ";
55	        s += strip_all_elaborated(t);
56	    };
57	    add(type_name<typename C::search_algo>());
58	    add(type_name<typename C::cache_traversal>());
59	    add(type_name<typename C::mapping>());
60	    add(type_name<typename C::path_compression>());
61	    add(type_name<typename C::node_type>());
62	    add(type_name<typename C::memory_layout>());
63	    add(type_name<typename C::allocator>());
64	    add(type_name<typename C::prefetch>());
65	    add(type_name<typename C::concurrency>());
66	    add(type_name<typename C::serialization>());
67	    add(type_name<typename C::telemetry>());
68	    add(type_name<typename C::value_handle>());
69	    add(type_name<typename C::isa>());
70	    add(type_name<typename C::index_organization>());
71	    add(type_name<typename C::io_dispatch>());
72	    add(type_name<typename C::migration_policy>());
73	    add(type_name<typename C::filter>());
74	    add(type_name<typename C::queuing_q1>()); // Doc 30 §8.0: queuing q1 (buffer_strategy)
75	    add(type_name<typename C::queuing_q2>()); // Doc 30 §8.0: queuing q2 (flush_policy)
