79	/// render_adhoc_module_source — der kompilierbare Modul-.cpp-Quelltext einer Permutation aus dem bereits
80	/// zusammengesetzten FQ-Achsen-Typ-Argument-Block. Reine Laufzeit-Funktion (kein Template) → wird sowohl
81	/// vom Template-Pfad emit_adhoc_modules<Engine> ALS AUCH von der F.4-Tools-Facade (ICodegenTool) genutzt,
82	/// damit das Emitter-Textformat an EINER Stelle definiert ist (DRY).
83	[[nodiscard]] inline std::string render_adhoc_module_source(int idx, std::string_view macro_args) {
84	    return "// AUTO-GENERATED by R5.G adhoc_emitter — Permutation " + std::to_string(idx) +
85	           " — DO NOT EDIT\n"
86	           "#include <builder/codegen/all_axes_umbrella.hpp>\n\n"
87	           "COMDARE_DEFINE_ANATOMY_MODULE_ADHOC(\n    " +
88	           std::string{macro_args} + ")\n";
89	}
