91	/// emit_adhoc_modules<Engine>(out_dir) — schreibt für JEDE Permutation des Engine ein Modul-.cpp nach
92	/// out_dir (Dateiname comdare_anatomy_perm_auto_<idx>.cpp) und liefert die geschriebenen Pfade.
93	/// Jedes .cpp ist standalone kompilierbar (nur Umbrella-Include + ADHOC-Makro).
94	template <class Engine>
95	[[nodiscard]] std::vector<std::filesystem::path> emit_adhoc_modules(std::filesystem::path const& out_dir) {
96	    std::error_code ec;
97	    std::filesystem::create_directories(out_dir, ec);
98	    std::vector<std::filesystem::path> files;
99	    int                                idx = 0;
100	    Engine::for_each_composition_type([&]<class C>() {
101	        std::filesystem::path const f = out_dir / ("comdare_anatomy_perm_auto_" + std::to_string(idx) + ".cpp");
102	        std::ofstream               out(f, std::ios::trunc);
103	        out << render_adhoc_module_source(idx, adhoc_macro_args<C>());
104	        files.push_back(f);
105	        ++idx;
106	    });
107	    return files;
108	}
