23	/// AnatomyPermutationDriver<TopicConfigSets...> — Spezialisierte
24	/// PermutationEngine-Facade die jeden Permutations-Punkt zu einer
25	/// SearchAlgorithmAnatomy<AdHocComposition> materialisiert.
26	///
27	/// Pflicht: TopicConfigSets muessen in der Topic-Slot-Convention-Reihenfolge
28	/// uebergeben werden (siehe AdHocComposition T0-T16 in composition_factory.hpp).
29	template <class... TopicConfigSets>
30	class AnatomyPermutationDriver {
31	    using Engine = pe::PermutationEngine<TopicConfigSets...>;
32	
33	public:
34	    using all_permutations = typename Engine::AllPermutations;
35	
36	    /// Anzahl Cartesian-Produkt-Punkte (Tiere) im Permutations-Raum
37	    [[nodiscard]] static constexpr std::size_t count() noexcept { return Engine::count(); }
38	
39	    /// Anzahl Topic-Achsen (Pflicht: 17 fuer vollstaendige Anatomie)
40	    [[nodiscard]] static constexpr std::size_t arity() noexcept { return Engine::arity; }
41	
42	    /**
43	     * @brief Iteriert ueber alle Permutationen und ruft Visitor mit dem
44	     *        instantiierten Algorithmus + composition_name.
45	     *
46	     * Visitor-Signatur: `void operator()(AlgoInstance&, std::string_view name)`.
47	     *
48	     * Beispiel:
49	     * @code
50	     *   AnatomyPermutationDriver<...>::for_each_animal(
51	     *       [](auto& algo, std::string_view name){
52	     *           algo.insert(42, 4242);
53	     *           std::cout << name << ": size=" << algo.size() << '\n';
54	     *       });
55	     * @endcode
56	     */
57	    template <class Visitor>
58	    static constexpr void for_each_animal(Visitor&& v) {
59	        Engine::for_each_permutation([&]<class P>() {
60	            using AdHoc = CompositionFromPermTuple<P>;
61	            SearchAlgorithmAnatomy<AdHoc> anatomy;
62	            // R5.B: Visitor erhaelt Anatomie + Name (KEINE Container-API mehr in Anatomie)
63	            // Fuer Container-Ops Builder muss AnatomyExecutionContext<AdHoc> wrappen.
64	            std::forward<Visitor>(v)(anatomy, AdHoc::name);
65	        });
66	    }
67	
68	    /**
69	     * @brief Compile-Time-Visitor mit Typen-Information (kein Runtime-Algorithmus).
70	     *
71	     * Visitor-Signatur: `template <class Composition> void operator()()`.
72	     * Verwendet fuer CacheEngineBuilder-Integration (jeden Composition-Type
73	     * zu eigenem .so/.dll builden).
74	     */
75	    template <class Visitor>
76	    static constexpr void for_each_composition_type(Visitor&& v) {
77	        Engine::for_each_permutation([&]<class P>() {
78	            using AdHoc = CompositionFromPermTuple<P>;
79	            std::forward<Visitor>(v).template operator()<AdHoc>();
80	        });
81	    }
82	};
