23	/// Die EINE endliche, gewählte Index-Liste in den statischen Teilbaum (View-Indizes, je → BinarySpec via view[i]).
24	/// `provenance` dokumentiert die Quelle/Reduktionsstufe (Audit: kein stilles Truncaten — Doc 28 §0).
25	struct BuildSelection {
26	    std::vector<std::size_t>  indices;    ///< gewählte View-Indizes (endlich, ≪ ∏)
27	    std::string               provenance; ///< "full" / "one_wise" / "explicit" / "pinned:<sig>" / "*-REFUSED-..."
28	    [[nodiscard]] std::size_t size() const noexcept { return indices.size(); }
29	    [[nodiscard]] bool        empty() const noexcept { return indices.empty(); }
