143	// V41.F.6.1 R5.D — VOLL-COVERAGE-Modus (--full-coverage): 1-wise-Ueberdeckungs-Stichprobe ueber die
144	// ECHTEN Achsen-Registry-Listen. Deckt ALLE Varianten der drei multi-varianten Achsen
145	// (search 17 × allocator 25 × layout 5) in max=25 Permutationen statt 2125 ab (each-value-Coverage,
146	// vgl. anatomy/combinatorial_coverage.hpp). Default bleibt der kuratierte Pilot → keine Regression.
147	// ─────────────────────────────────────────────────────────────────────────────
148	namespace fullcov {
149	using SearchList                  = ce::traversal::axis_03a_search_algo::AllStrategies;
150	using AllocList                   = ce::allocator::axis_06_allocator::AllVendors;
151	using LayoutList                  = ce::memory_layout::axis_05_memory_layout::AllLayouts;
152	inline constexpr std::size_t kNs  = mp::mp_size<SearchList>::value;
153	inline constexpr std::size_t kNa  = mp::mp_size<AllocList>::value;
154	inline constexpr std::size_t kNl  = mp::mp_size<LayoutList>::value;
155	inline constexpr std::size_t kMax = (kNs > kNa ? (kNs > kNl ? kNs : kNl) : (kNa > kNl ? kNa : kNl));
156	
157	// Zeile r → Achse i = (r mod n_i): jede Variante jeder Achse erscheint mind. 1× (1-wise).
158	template <class R>
159	using SampledComposition = ana::AdHocComposition<mp::mp_at_c<SearchList, R::value % kNs>, // T0  search_algo
160	                                                 CT, MP, PC, NT,                          // T1..T4
161	                                                 mp::mp_at_c<LayoutList, R::value % kNl>, // T5  memory_layout
162	                                                 mp::mp_at_c<AllocList, R::value % kNa>,  // T6  allocator
163	                                                 PF, CC, SE, TM, VH, IS, IO, IOD, MG, FL, // T7..T16
164	                                                 Q1, Q2>; // T17 queuing_q1, T18 queuing_q2 (19-Slot, Doc 30 §8.0)
165	
166	using SampleList = mp::mp_transform<SampledComposition, mp::mp_iota_c<kMax>>;
167	
168	struct SampleEngine {
169	    [[nodiscard]] static constexpr std::size_t count() noexcept { return mp::mp_size<SampleList>::value; }
170	    template <class Visitor>
171	    static constexpr void for_each_composition_type(Visitor&& v) {
172	        mp::mp_for_each<mp::mp_transform<mp::mp_identity, SampleList>>([&](auto id) {
173	            using C = typename decltype(id)::type;
174	            v.template operator()<C>();
175	        });
176	    }
177	};
178	static_assert(SampleEngine::count() == kMax, "1-wise-Stichprobe muss max(Achsen-Varianten) Permutationen haben");
