184	// Emittiert den Raum des gewaehlten Engine + schreibt manifest.txt (idx → search/allocator/memory_layout).
185	template <class Engine>
186	int emit_with(std::string const& out_dir, char const* mode) {
187	    auto const files = cg::emit_adhoc_modules<Engine>(out_dir);
188	    for (auto const& f : files) std::cout << f.string() << "\n";
189	    std::ofstream manifest(std::filesystem::path{out_dir} / "manifest.txt", std::ios::trunc);
190	    int           mi = 0;
191	    Engine::for_each_composition_type([&]<class C>() {
192	        std::string const line = std::to_string(mi) + "\t" + std::string{C::search_algo::name()} + "\t" +
193	                                 std::string{C::allocator::name()} + "\t" + std::string{C::memory_layout::name()};
194	        std::cerr << "  [idx " << line << "]\n";
195	        manifest << line << "\n";
196	        ++mi;
197	    });
198	    std::cerr << "comdare-adhoc-emitter: " << files.size()
199	              << " Permutations-Modul-.cpp geschrieben (count=" << Engine::count() << ", Modus=" << mode
200	              << ", manifest.txt geschrieben).\n";
201	    return files.empty() ? 2 : 0;
202	}
