205	int main(int argc, char** argv) {
206	    if (argc < 2) {
207	        std::cerr << "Usage: comdare-adhoc-emitter <output-dir> [--full-coverage]\n"
208	                     "  Default: kuratierter 3-Achsen-Pilot (search×allocator×memory_layout = 48).\n"
209	                     "  --full-coverage: 1-wise-Ueberdeckung ueber ALLE Achsen-Varianten "
210	                     "(17×25×5 → 25 Permutationen, jede Variante mind. 1×).\n";
211	        return 1;
212	    }
213	    std::string const out_dir       = argv[1];
214	    bool              full_coverage = false;
215	    for (int i = 2; i < argc; ++i)
216	        if (std::string{argv[i]} == "--full-coverage") full_coverage = true;
217	
218	    return full_coverage ? emit_with<fullcov::SampleEngine>(out_dir, "full-coverage-1wise")
219	                         : emit_with<PilotEngine>(out_dir, "kuratiert-3achsen");
